function adminColor32D(vId,code){const idx=Math.max(0,ALPHA32D.indexOf(String(code||'A')[0])),hue=(Number(vId)*57+idx*47+28)%360;return{fill:`hsla(${hue},70%,55%,.24)`,line:`hsla(${hue},82%,70%,.95)`};}
function drawAdmin32D(ui){const g=ui._mapGeom,c=ui.q('worldCanvas');if(!g||!c)return;const ctx=c.getContext('2d'),{cell,ox,oy}=g,w=ui.world;ctx.save();for(const v of w.activeVillages||[]){const a=adminModel32D(v,w);for(const r of a.regions||[]){const col=adminColor32D(v.id,r.code);for(const id of r.tiles||[]){const t=w.map.get(id);if(!t)continue;ctx.fillStyle=col.fill;ctx.fillRect(ox+t.x*cell,oy+t.y*cell,cell,cell);ctx.strokeStyle=col.line;ctx.lineWidth=Math.max(1,cell*.035);ctx.strokeRect(ox+t.x*cell+1,oy+t.y*cell+1,cell-2,cell-2);}const h=w.map.get(r.hubTileId);if(h){const x=ox+(h.x+.5)*cell,y=oy+(h.y+.5)*cell,rad=Math.max(5,cell*.23);ctx.fillStyle='rgba(10,22,37,.88)';ctx.beginPath();ctx.arc(x,y,rad,0,Math.PI*2);ctx.fill();ctx.strokeStyle=col.line;ctx.lineWidth=Math.max(2,cell*.07);ctx.stroke();ctx.fillStyle='#fff';ctx.font=`700 ${Math.max(9,Math.min(13,cell*.28))}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(r.code,x,y);}}}ctx.restore();const leg=ui.q('v15LayerLegend');if(leg)leg.textContent='행정권 · A/B/C는 국가별 영속 행정권 코드 · 원형 문자는 행정 중심지';}
function drawMilitary32D(ui){if(NS.V033H)return;const g=ui._mapGeom,c=ui.q('worldCanvas');if(!g||!c)return;const ctx=c.getContext('2d'),{cell,ox,oy}=g,w=ui.world,groups=new Map();for(const v of w.activeVillages||[])for(const f of ensureFormations32D(v,w)){const n=formationPeople32D(v,f).length;if(!n)continue;const key=Number(f.tileId),a=groups.get(key)||[];a.push({v,f,n});groups.set(key,a);}ctx.save();for(const[id,arr]of groups){const t=w.map.get(id);if(!t)continue;const total=arr.reduce((a,x)=>a+x.n,0),x=ox+(t.x+.5)*cell,y=oy+(t.y+.5)*cell,col=(NS.NATION_COLORS||['#62a8ff','#74d69c','#ff8b91','#bd9cff'])[arr[0].v.id%(NS.NATION_COLORS||[]).length]||'#69adff',label=arr.length>1?`⚔${total}`:`▲${total}`;ctx.font=`700 ${Math.max(9,Math.min(14,cell*.29))}px system-ui`;const tw=ctx.measureText(label).width+8,hh=Math.max(15,cell*.30);ctx.fillStyle='rgba(8,18,31,.88)';ctx.strokeStyle=col;ctx.lineWidth=Math.max(1.5,cell*.04);ctx.beginPath();ctx.roundRect?.(x-tw/2,y-hh/2,tw,hh,4);if(ctx.roundRect){ctx.fill();ctx.stroke();}else{ctx.fillRect(x-tw/2,y-hh/2,tw,hh);ctx.strokeRect(x-tw/2,y-hh/2,tw,hh);}ctx.fillStyle='#fff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,x,y);}ctx.restore();const leg=ui.q('v15LayerLegend');if(leg)leg.textContent='군사 · ▲ 실제 Person 기반 Formation · 타일 단위 위치/이동 · 전투는 아직 비활성';}
function setupMapControls32D(ui){const bar=document.querySelector('#view-map .map-toolbar'),layer=ui.q('v15LayerSelect');if(layer&&!layer.querySelector('option[value="military32D"]'))layer.insertAdjacentHTML('beforeend','<option value="military32D">군사</option>');let sel=document.getElementById('v32dMapStyle');if(bar&&!sel){sel=document.createElement('select');sel.id='v32dMapStyle';sel.innerHTML='<option value="nation">국가 중심</option><option value="balanced" selected>균형</option><option value="terrain">지형 중심</option>';bar.appendChild(sel);sel.onchange=()=>{ui.mapTerritoryStyle32D=sel.value;ui.renderMap();};}if(sel){ui.mapTerritoryStyle32D=ui.mapTerritoryStyle32D||'balanced';sel.value=ui.mapTerritoryStyle32D;}}

