 NS.UI.prototype.renderHeader=function(){headBefore32D.call(this);document.title='Village Observer V0.32D';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.32D</strong>';const st=this.q('runtimeStatus');if(st)st.textContent='✓ V0.32D Formation 지도 · 통계 재편 · 행정권 A/B/C · 지형 중심 지도 · 로그 압축';};
