if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.32D'))NS.PATCH_NOTES.unshift({version:'V0.32D',date:'2026-09-26',title:'Formation 지도 · 통계/행정/지형 관측 개편',summary:'실제 Person Cohort를 지도 위 Formation으로 지속 관측하고, 통계·행정권·지도 표현·장기 로그를 123년 장기주행 결과에 맞춰 정리합니다.',sections:[['Formation V1',['각 현역 Cohort에 정확한 tileId를 가진 Formation을 생성합니다.','AI가 국경·행정 중심·철산업·도로·인구와 군사교리를 평가해 목표 타일을 정하고 자국 영토를 한 칸씩 이동합니다.','Garrison은 고정 거점으로 유지되고 Formation은 움직이는 부대입니다. 전투·점령·사상자는 아직 없습니다.']],['통계·가격',['평균 건강·허기·행복을 생활 상태로 통합합니다.','지식은 누적·국가별 평균·1인당으로, 골드는 전체 통화량·국가 금고·정착지 시장·개인 보유로 그룹화합니다.','통계 표기는 한국어 중심으로 정리하고 Gold 표기는 골드로 통일합니다.','신규 세계 초기 가격은 목재 0.35, 석재 0.49, 철광석 0.90으로 시작합니다.']],['행정·지도',['국가별 행정권을 A/B/C 순서의 영속 코드로 표시합니다.','비수도 행정 중심지가 연속 6년 유지되면 고대 행정청을 우선 건설합니다.','지도 표현에 국가 중심·균형·지형 중심을 추가하며 지형 중심에서도 국경선은 유지합니다.']],['로그',['INTERNAL_LOGISTICS·식량 접근 차단·긴급 식량 수송·재정 차단 등 고빈도 로그는 5년이 지나면 연간 요약으로 압축합니다.','최근 5년 상세는 그대로 유지해 원인 분석이 가능하도록 합니다.','식량 접근 차단·긴급 수송·아사 누적 telemetry를 별도로 보강합니다.']]]});
(function(){const KEY='village-observer-v0-32d',fallback=['village-observer-v0-32c2','village-observer-v0-32c1a','village-observer-v0-32c1','village-observer-v0-32c','village-observer-v0-32b','village-observer-v0-32a','village-observer-v0-31i','village-observer-v0-31h','village-observer-v0-31g','village-observer-v0-31f','village-observer-v0-31a','village-observer-v0-31'];function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v032D-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){compactLogs32D(w.telemetry,w,true);dl(`village-observer-v032D-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){dl(`village-observer-v032D-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+w.telemetry.snapshotsCSV(),'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attach32D(NS.V019.worldFromMapData(JSON.parse(await file.text())));}};})();

